'use strict';
const $=s=>document.querySelector(s),h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=u=>{try{const x=new URL(u);return ['http:','https:'].includes(x.protocol)?h(u):'#'}catch{return '#'}};
const source=(u,t)=>`<a href="${safeURL(u)}" target="_blank" rel="noopener noreferrer">${h(t)} ↗</a>`;
function stored(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let selected='overview',view='ideas',focus=0,query='',topic='全部',format='text',collection=false,methodFormat=1;
const priorSaved=stored('atlas-saved-research-v2',[]),preservedIds=new Set(['zara','matt-pocock','emil-kowalski','karpathy']);
const saved=new Set(stored('atlas-saved-research-v3',priorSaved.filter(k=>preservedIds.has(k.split(':')[0]))));
const legacySaved=[...stored('atlas-saved',[]),...priorSaved.filter(k=>!preservedIds.has(k.split(':')[0]))];
const p=()=>BUILDERS.find(p=>p.id===selected),batch=()=>X_INSIGHTS.profiles.find(x=>x.id===selected);
const reviewed=author=>author.researchStatus==='reviewed';
const researched=author=>['reviewed','partial'].includes(author.researchStatus);
const researchPeople=()=>BUILDERS.filter(researched);
const reviewedPeople=()=>BUILDERS.filter(reviewed);
const partialPeople=()=>BUILDERS.filter(a=>a.researchStatus==='partial');
function workSource(w){return {url:w.url,published:w.date,title:w.title,locator:w.locator,excerpt:w.excerpt,access:w.access}}
function items(){if(!p())return [];if(view==='works')return p().works.map(w=>({...w,text:w.summary,sources:[workSource(w)],kind:'work'}));if(view==='x')return (batch()?.insights||[]).map(x=>({...x,text:x.summary,kind:'x'}));if(!researched(p()))return [];return p().ideas.map((i,n)=>({...i,sources:(i.sourceIndices||[i.source||0]).map(idx=>workSource(p().works[idx])),kind:'idea',explanation:LEARNING_IDEAS[selected]?.[n]||i.text}))}
const kindTitle=()=>({ideas:'研究观点',x:reviewed(p()||{})?'X 快照观点':'旧 X 总结 · 待复核',works:researched(p()||{})?'研究材料':'旧资料 · 待复核',learn:'理解与练习'}[view]);
function researchBadge(author){const status=author.researchStatus;return `<span class="research-badge ${h(status)}">${status==='reviewed'?'专题复核':status==='partial'?'初步整理':'TODO'}</span>`}
function researchHTML(){const r=p().research;return `<section class="research-scope ${h(p().researchStatus)}"><div>${researchBadge(p())}<strong>${reviewed(p())?'限定范围的主题研究':researched(p())?'材料已读，代表性仍待扩展复核':'待深入研究'}</strong><span class="small">${h(r.reviewedAt||'尚未复核')}</span></div><p>${h(researched(p())?r.correction:'主要观点尚未完成系统研究。旧资料仅保留为线索。')}</p>${researched(p())?`<details><summary>${r.sourceCount} 份研究材料 · 查看范围与缺口</summary><p>${h(r.scope)}</p><p>${h(r.selection)}</p><p>${h(r.xScope)}</p><p>${h(r.limitations)}</p>${source('https://github.com/holynova/builder-atlas/blob/main/research/'+selected+'.md','逐条研究记录')}</details>`:''}</section>`}
const mark=()=>`${selected}:${view}:${focus}`;
function avatar(author){return `<span class="avatar" aria-hidden="true">${h(author.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span>`}
function profiles(){return BUILDERS.filter(p=>(topic==='全部'||p.category===topic)&&JSON.stringify([p.name,p.short,p.category,p.thesis,p.summary,p.ideas,p.works,LEARNING[p.id]]).toLowerCase().includes(query.toLowerCase()))}
function navHTML(){return `<div class="rail-title">人物与信息源 <span class="count-chip">30</span></div><a class="nav-entry ${selected==='overview'&&!collection?'active':''}" href="#overview">⌂ 理解地图与阅读路线</a><button class="nav-entry ${collection?'active':''}" data-action="collection">♡ 我的收藏 <span>${saved.size}</span></button><div class="search-box"><span aria-hidden="true">⌕</span><input id="search" placeholder="找人物、产品或观点" value="${h(query)}" aria-label="搜索人物、产品或观点"></div><label class="sr-only" for="topic">主题分类</label><select id="topic">${['全部',...new Set(BUILDERS.map(p=>p.category))].map(c=>`<option ${c===topic?'selected':''}>${h(c)}</option>`).join('')}</select><nav class="people-nav" aria-label="人物目录">${profiles().map(author=>`<a class="person ${author.id===selected&&!collection?'selected':''}" href="#${author.id}" ${author.id===selected?'aria-current="page"':''}>${avatar(author)}<span><strong>${h(author.name)}</strong><small>${h(author.short)} ${researchBadge(author)}</small></span><span class="person-arrow">↗</span></a>`).join('')||'<p class="empty">没有匹配结果，试试其他关键词。</p>'}</nav><div class="rail-footer">${profiles().length} / 30 个匹配 · <a href="#method">研究方法与来源 ↗</a></div>`}
function profileHead(){return `<div class="work-profile">${avatar(p())}<div><span class="eyebrow">${h(p().category)}</span><h1>${h(p().name)}</h1></div></div><p class="work-role">${h(p().role)}</p><p class="work-thesis">${h(p().thesis)}</p>${researchHTML()}<div class="work-tabs" aria-label="档案内容">${[['ideas',researched(p())?'研究观点':'TODO'],['x',reviewed(p())?'X 快照':'旧 X · 待复核'],['works',researched(p())?'研究材料':'旧资料'],['learn','理解与练习']].map(([v,t])=>`<button data-view="${v}" aria-pressed="${v===view}">${t}${v==='x'&&batch()?.count?'<span class="tab-dot" aria-label="已有样本"></span>':''}</button>`).join('')}</div>`}
function listHTML(){if(!researched(p())&&['ideas','learn'].includes(view))return `<div class="empty-state"><span class="eyebrow">RESEARCH TODO</span><h2>这份档案等待深入研究</h2><p>接下来需要阅读本人文章、推文与公开访谈，核对哪些主题反复出现、哪些只是单次讨论，再逐条绑定依据。</p><p>原有观点已撤出当前展示。你仍可打开旧资料作为阅读线索。</p><button class="save" data-view="works">查看旧资料 →</button></div>`;if(view==='learn')return `<section class="learning-task"><span class="eyebrow">START WITH A QUESTION</span><h2>${h(LEARNING[selected][0])}</h2><p>${h(p().thesis)}</p><div class="learning-map">${p().ideas.map((i,n)=>`<button data-action="learn-idea" data-index="${n}"><span>0${n+1}</span><strong>${h(i.title)}</strong><small>理解观点与依据 ↗</small></button>`).join('')}</div><h3>把观点放进实际任务</h3><p>${h(LEARNING[selected][1])}</p><label for="note">我的尝试与结果</label><textarea id="note" placeholder="写下准备尝试的任务，以及你会怎样检查结果。">${h(stored('atlas-note:'+selected,''))}</textarea><small>笔记仅保存在当前浏览器。练习与图解为编辑设计，不是作者原话。</small></section>`;
const data=items();if(!data.length)return `<div class="empty-state"><span class="eyebrow">COLLECTION PENDING</span><h2>本轮尚无有效 X 样本</h2><p>此账号本轮没有可用的近期 X 总结。文章研究和推文采集分别记录，不代表作者没有发表观点。</p><p class="micro">${h(p().research.xScope||"采集情况尚待补充。")}</p><button class="save" data-view="ideas">阅读代表文章观点 →</button></div>`;
return `<div class="work-toolbar"><span>${data.length} 条${kindTitle()}</span><span>选择一条查看依据 →</span></div>${view==='x'?`<p class="collection-status">${!reviewed(p())?'本页旧 X 总结尚未逐条复核，请以研究材料中列出的帖子为准。<br>':''}${batch().count===37?'部分样本 · 37 条；未确认最近 100 条完整覆盖':'100 条主页样本'} · 采集于 ${batch().collectedDate||X_INSIGHTS.collectedDate}<br>本人帖子日期：${h(batch().ownPostDateRange.join(' — '))}</p>`:''}<div class="insight-list">${data.map((i,n)=>`<button class="insight-row ${focus===n?'chosen':''}" data-index="${n}" aria-pressed="${focus===n}"><div class="row-overline"><span>${h(i.type||kindTitle())} ${String(n+1).padStart(2,'0')}</span><span>${h(i.sources[0]?.published||'')}</span></div><h2>${h(i.title)}</h2><p>${h(i.text)}</p><div class="row-bottom"><span>${i.sources.length} 条来源</span><span>${saved.has(`${selected}:${view}:${n}`)?'已收藏 ✓':'阅读 →'}</span></div></button>`).join('')}</div>`}
function evidenceHTML(){const all=items(),i=all[Math.min(focus,all.length-1)];if(!i)return `<div class="evidence-label">阅读与核对</div><p class="empty">选择研究观点或材料，即可查看出处与阅读范围。</p>${authorLinks()}`;
return `<div class="evidence-label"><span>阅读与核对</span><span class="small">${String(focus+1).padStart(2,'0')} / ${all.length}</span></div><span class="tag">${kindTitle()}</span><h2>${h(i.title)}</h2>${i.kind==='idea'?`<div class="format-tabs">${[['text','短句'],['diagram','图解'],['steps','分步']].map(([f,t])=>`<button data-format="${f}" aria-pressed="${format===f}">${t}</button>`).join('')}</div>`:''}<div class="evidence-summary">${format==='diagram'&&i.kind==='idea'?`<div class="mini-map"><span>核心主张</span><p>${h(p().thesis)}</p><div aria-hidden="true">↓</div><strong>${h(i.title)}</strong></div><p class="micro">箭头表示主张与相关观点的联系。</p>`:''}<span class="eyebrow">${i.kind==='work'?'内容概括':'观点概括'}</span><p>${h(i.kind==='idea'?i.explanation:i.text)}</p>${format==='steps'&&i.kind==='idea'?`<p class="micro">第 ${focus+1} / ${all.length} 步。使用下方箭头逐条理解观点。</p>`:''}</div>${i.kind==='work'?`<div class="work-reading"><h3>为什么值得读</h3><p>${h(i.why)}</p><small>${h(i.author)} · ${h(i.date)}</small>${i.access?`<p class="access-note">${h(i.access)}</p>`:''}${i.evidence?source(i.evidence,'已读取的逐字稿／镜像依据'):''}</div>`:''}${i.kind==='idea'?`<div class="claim-context"><h3>为何列入本页</h3><p>${h(i.representativeness)}</p><h3>适用边界与反例</h3><p>${h(i.boundary)}</p></div>`:''}<div class="evidence-sources"><h3>出处与阅读范围</h3>${i.sources.map((s,n)=>`<div class="evidence-source"><span class="source-glyph">↗</span><div>${source(s.url,s.title||'打开本人帖子 '+(n+1))}<small>${h(s.published)}</small>${s.locator?`<p class="source-location">定位：${h(s.locator)}</p>`:''}${s.excerpt?`<blockquote lang="en">${h(s.excerpt)}</blockquote>`:''}${s.access?`<p class="access-note">${h(s.access)}</p>`:''}</div></div>`).join('')}</div><div class="evidence-footer"><button class="save" data-action="save" aria-pressed="${saved.has(mark())}">${saved.has(mark())?'已收藏 ✓':'收藏内容 ＋'}</button><div class="mini-nav"><button data-action="prev" aria-label="上一条内容" ${focus===0?'disabled':''}>←</button><button data-action="next" aria-label="下一条内容" ${focus===all.length-1?'disabled':''}>→</button></div></div>${view==='x'?`<details class="boundary"><summary>采集范围与阅读边界</summary><p>主页样本包含原创、引用、转推及部分回复，排除置顶。不是最近 100 条原创发言；总结排除纯转推，并区分引用者与嘉宾观点。未逐一核验附带图片、视频或外链。纯转推 ${batch().reposts} 条，带引用的本人帖子 ${batch().quotes} 条。当前批次是固定快照。</p></details>`:''}<div class="reading-note"><span class="eyebrow">阅读提示 · 编辑判断</span><p>${h(p().note)}</p></div>${authorLinks()}`}
function authorLinks(){return `<div class="author-contact"><span class="eyebrow">FOLLOW THE SOURCE</span>${source(p().x,'关注 '+p().name)}${source(p().home,'网站与作品')}<details><summary>${researched(p())?'研究简介':'旧版简介 · 待复核'}</summary><p>${h(p().summary)}</p><small>名单依据：${h(p().origin)}。职务以引用资料发表时的语境为准。</small></details></div>`}
function collectionHTML(){const entries=[...saved].map(k=>{const [id,v,n]=k.split(':');const author=BUILDERS.find(p=>p.id===id);if(!author)return null;const item=v==='works'?author.works[n]:v==='x'?X_INSIGHTS.profiles.find(x=>x.id===id)?.insights?.[n]:author.ideas[n];return item?{k,author,item}:null}).filter(Boolean);return `<div class="overview-heading"><span class="eyebrow">MY READING LIST</span><h1>我的收藏</h1><p>保存在当前浏览器，方便回到观点与原文。</p>${legacySaved.length?`<p class="collection-status">检测到 ${legacySaved.length} 条旧版收藏。旧记录仍保存在浏览器中；观点已重写，因此没有按旧序号映射到新版，避免指向错误内容。</p>`:""}</div>${entries.length?entries.map(e=>`<button class="insight-row" data-saved="${h(e.k)}"><div class="row-overline">${h(e.author.name)}</div><h2>${h(e.item.title)}</h2><p>${h(e.item.text||e.item.summary)}</p><div class="row-bottom">打开内容与依据 ↗</div></button>`).join(''):'<p class="empty-state">还没有收藏。进入人物档案，在右栏点击“收藏内容”。</p>'}`}

const escapeHTML=h,link=source;
const methodNames=['清楚的文字','关系图解','交互网页','讲解视频'];
const methodNotes=[
['把一句话拆成可检查的意思。','Karpathy 建议用 ASD-STE100，或接近它的写法，让模型写得更清楚。这里借用短句、明确动作和稳定术语的原则；中文示例不声称符合该英文规范。'],
['把关系画出来，减少脑内拼图。','图解适合结构、步骤和关系。先看全貌，再选择一个节点读细节。图里应说明连线的含义，避免把并列观点误读为因果。'],
['让读者操作，看到条件如何改变结果。','HTML 网页可以把解释变成可操作的软件。它可以服务一次具体的理解任务，不一定需要长期维护成一个产品。'],
['用时间顺序、画面和声音共同解释。','Karpathy 最看好按主题定制的讲解视频。先设计每一幕要解释什么，再生成画面与旁白。本页提供脚本示例和分步网页讲解，尚未生成视频文件。']
];
function renderMethod(){const focused=document.activeElement?.dataset?.method;const [title,note]=methodNotes[methodFormat];let demo='';
if(methodFormat===0)demo='<div class="plain-example"><p><b>Agent 写完代码。</b>这只表示代码已生成。</p><p><b>运行检查。</b>确认代码是否满足任务条件。</p><p><b>人核对结果。</b>决定是否交付。</p></div>';
if(methodFormat===1)demo='<div class="example-flow"><span>Agent 生成代码</span><i>→</i><span>工具检查结果</span><i>→</i><span>人判断是否交付</span></div><p class="micro">箭头表示示例中的执行顺序。检查失败时，应返回修改。</p>';
if(methodFormat===2)demo='<div class="check-demo"><p>试着改变验收条件，观察结论。</p><label><input type="checkbox" id="test-check">自动检查通过</label><label><input type="checkbox" id="human-check">人已核对任务结果</label><output id="demo-result" aria-live="polite">已生成代码，尚未完成验收。</output><p class="micro">这是教学示例，没有运行真实代码或调用模型。</p></div>';
if(methodFormat===3)demo='<ol class="storyboard"><li><b>第一幕：生成</b><span>画面显示代码出现。旁白：“写完代码，还不等于完成任务。”</span></li><li><b>第二幕：检查</b><span>画面显示测试与反馈。旁白：“检查失败，就返回修改。”</span></li><li><b>第三幕：判断</b><span>画面显示人核对结果。旁白：“工具提供证据，人决定是否交付。”</span></li></ol><p class="micro">视频脚本示例，未生成视频或音频。</p>';
$('#method-demo').innerHTML=`<div class="demo-heading"><span class="eyebrow">${String(methodFormat+1).padStart(2,'0')} / ${methodNames[methodFormat]}</span><h3>${title}</h3></div><p>${note}</p><div class="demo-surface"><span class="micro">同一个例子：怎样理解 Agent 完成任务？</span>${demo}</div>`;
$('#method-formats').innerHTML=methodNames.map((n,i)=>`<button data-method="${i}" aria-pressed="${i===methodFormat}"><span>0${i+1}</span>${n}</button>`).join('');if(focused!==undefined)document.querySelector(`[data-method="${focused}"]`)?.focus({preventScroll:true});}
function overviewHTML(){return `<div class="overview-heading"><span class="eyebrow">A WORKSPACE FOR UNDERSTANDING</span><h1>先读本人材料，<br>再判断代表性。</h1><p>30 份档案均有来源可追溯的观点。4 份完成专题复核，26 份完成初步整理；每条归纳都保留材料范围、选入理由与边界。</p><div class="overview-stats"><span><strong>${reviewedPeople().length}</strong>专题复核 · 限定范围</span><span><strong>${partialPeople().length}</strong>初步整理 · 待扩展复核</span><span><strong>${researchPeople().reduce((n,p)=>n+p.works.length,0)}</strong>材料引用 · 含共享来源</span></div></div><section class="routes-section"><span class="eyebrow">RESEARCHED PROFILES</span><h2>四份专题档案</h2><div class="reviewed-grid">${['zara','matt-pocock','emil-kowalski','karpathy'].map(id=>{const a=BUILDERS.find(p=>p.id===id);return `<a href="#${id}" class="reviewed-card">${researchBadge(a)}<h3>${h(a.name)}</h3><p>${h(a.thesis)}</p><small>${a.ideas.length} 条研究观点 · ${a.works.length} 份材料 ↗</small></a>`}).join('')}</div></section><section class="routes-section"><span class="eyebrow">NEW RESEARCH NOTES</span><h2>其余 26 份档案，已补入初步主题</h2><p class="micro">单篇文章、访谈摘录或公开预览只能支持限定主题。进入档案查看已读章节与仍缺的证据。</p><details class="initial-details"><summary>浏览全部 26 份初步档案 →</summary><div class="initial-grid">${partialPeople().map(a=>`<a href="#${a.id}" class="initial-card"><div>${researchBadge(a)}<small>${a.works.length} 份材料</small></div><h3>${h(a.name)}</h3><p>${h(a.thesis)}</p></a>`).join('')}</div></section><section class="routes-section"><span class="eyebrow">READING PATHS</span><h2>带着一个问题去读</h2><div class="routes">${ROUTES.map(r=>`<article class="route"><p class="micro">${h(r.question)}</p><h3>${h(r.title)}</h3><ol>${r.ids.map((id,n)=>`<li><a href="#${id}"><span>0${n+1}</span><div><strong>${h(r.labels[n])}</strong><small>${h(BUILDERS.find(p=>p.id===id).name)}</small></div><i>↗</i></a></li>`).join('')}</ol></article>`).join('')}</div><p class="micro">路线与练习由编辑设计，不是作者之间的合作关系或排名。</p></section><section class="method-section"><span class="eyebrow">KARPATHY'S METHOD</span><h2>让输出帮助你理解</h2><div id="method-formats" class="method-formats"></div><div id="method-demo" class="method-demo"></div><p class="micro">方法依据：${source('https://x.com/karpathy/status/2105819303471976479','Karpathy 本人帖子')}。例子由本档案编写。</p></section><section id="method" class="method-section"><span class="eyebrow">ABOUT THE RESEARCH</span><h2>来源可追溯，代表性仍需判断。</h2><p>Zara Zhang、Matt Pocock、Emil Kowalski 与 Andrej Karpathy 保留专题复核。其余 26 份档案新增 56 条材料引用、74 条主题归纳，标为初步整理。每条观点均有来源、定位、选入理由与边界；初步整理不等于已确认作者的完整核心思想。</p><p>专题复核时 Zara 与 Matt 各补采 100 条 X 主页帖子；Karpathy 复用此前样本，Emil 依据本人文章。此次扩展未重新采集 26 个账号的最近 100 条；只复核材料中列明的指定本人帖子。旧 X 总结仍单独标为待复核。媒体、外链及完整视频未逐一核验。</p><p>原始访谈可能只有节目方摘要、摘录或付费墙前预览，均明确标注，不声称已读完整回答。主持人、嘉宾与联名作者区分归属；Google Labs、Claude 展示官方团队方向。材料数为各档案引用数，同一访谈可能被两位嘉宾各引用。名单不等于观点研究。</p><div class="data-links">${source('https://github.com/zarazhangrui/follow-builders','名单源头')}<a href="research.json" download>研究数据与状态 JSON ↓</a><a href="x-insights.json" download>X 观点与范围 JSON ↓</a><a href="learning.json" download>练习与阅读路线 JSON ↓</a></div></section>`}
function render(){const active=document.activeElement?.id,pos=active==='search'?document.activeElement.selectionStart:null;const isOverview=!p()||collection;
$('#app').innerHTML=`<div class="workbench"><header class="topbar"><a href="#overview" class="brand"><span class="brand-icon">B</span>Builder Atlas</a><div class="workspace-label"><span class="status-dot"></span>研究空间 <span class="muted">/</span> 人物观点库</div><span class="small">研究更新 · 2026.10.04</span>${source('https://github.com/holynova/builder-atlas','GitHub')}</header><div class="workbench-layout ${isOverview?'overview-layout':''}"><aside class="work-directory">${navHTML()}</aside><main class="insight-column" id="main">${collection?collectionHTML():p()?profileHead()+listHTML():overviewHTML()}<footer class="release-footer">BUILDER ATLAS · v1.4.0 <span>观点为中文转述 · 原文版权属于各作者</span></footer></main>${!isOverview?`<aside class="evidence-column" aria-label="阅读与核对">${evidenceHTML()}</aside>`:''}</div></div>`;
if(!p()&&!collection)renderMethod();document.title=p()?`${p().name} · Builder Atlas`:'Builder Atlas · 研究工作台';if(active==='search'){const input=$('#search');input.focus();input.setSelectionRange(pos,pos)}}
function route(){const id=location.hash.slice(1);selected=BUILDERS.some(p=>p.id===id)?id:'overview';collection=false;view='ideas';focus=0;format='text';render();if(id==='method')$('#method')?.scrollIntoView();else window.scrollTo({top:0,behavior:'instant'})}
$('#app').addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;render()}if(e.target.id==='note')localStorage.setItem('atlas-note:'+selected,JSON.stringify(e.target.value));if(['test-check','human-check'].includes(e.target.id)){const checks=Number($('#test-check').checked)+Number($('#human-check').checked);$('#demo-result').textContent=['已生成代码，尚未完成验收。','只完成一项检查，还需核对另一项。','示例中的两项验收已完成，可以考虑交付。'][checks]}});
$('#app').addEventListener('change',e=>{if(e.target.id==='topic'){topic=e.target.value;render()}});
$('#app').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
if(b.dataset.method!==undefined){methodFormat=Number(b.dataset.method);renderMethod();return}
if(b.dataset.saved){const [id,v,n]=b.dataset.saved.split(':');collection=false;selected=id;view=v;focus=Number(n);history.replaceState(null,'','#'+id);render();return}
if(b.dataset.view){view=b.dataset.view;focus=0;format='text';render();return}
if(b.dataset.format){format=b.dataset.format;render();return}
if(b.dataset.action==='learn-idea'){view='ideas';focus=Number(b.dataset.index);format='diagram';render();return}
if(b.dataset.index!==undefined){focus=Number(b.dataset.index);render();if(innerWidth<801)$('.evidence-column')?.scrollIntoView({behavior:'instant'});return}
if(b.dataset.action==='collection'){collection=true;render();window.scrollTo(0,0);return}
if(b.dataset.action==='save'){saved.has(mark())?saved.delete(mark()):saved.add(mark());localStorage.setItem('atlas-saved-research-v3',JSON.stringify([...saved]));render();return}
if(b.dataset.action==='next'||b.dataset.action==='prev'){focus=Math.max(0,Math.min(items().length-1,focus+(b.dataset.action==='next'?1:-1)));render()}});
$('#app').addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(a&&a.getAttribute('href')===location.hash)route()});
window.addEventListener('hashchange',()=>{if(location.hash!=='#main')route()});route();
